import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
});

import js from "@eslint/js";
import prettier from "eslint-config-prettier";
import globals from "globals";
import tseslint from "typescript-eslint";

export default tseslint.config(
  {
    ignores: ["dist/**", "node_modules/**", "playwright-report/**", "test-results/**"],
  },
  js.configs.recommended,
  tseslint.configs.recommended,
  prettier,
  {
    files: ["src/**/*.{ts,tsx}"],
    languageOptions: {
      globals: globals.browser,
    },
  },
  {
    files: ["*.config.ts", "playwright.config.ts", "eslint.config.js"],
    languageOptions: {
      globals: globals.node,
    },
  },
);

{
  "printWidth": 100,
  "singleQuote": false
}

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App";
import "./styles.css";

const root = document.getElementById("root");
if (!root) {
  throw new Error("Root element is missing.");
}

createRoot(root).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

export function App() {
  return (
    <main>
      <h1>Footwork</h1>
      <p>Toolchain shell. The Soundprint interface is not part of this build.</p>
    </main>
  );
}

:root {
  color-scheme: light;
  --text: #1a1a1a;
  --bg: #f7f4ef;
  --focus: #0b57d0;
}

body {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  background: var(--bg);
  color: var(--text);
}

main {
  max-width: 40rem;
  padding: 2rem 1.25rem;
}

h1 {
  font-size: 2rem;
  line-height: 1.2;
}

p {
  font-size: 1.125rem;
  line-height: 1.5;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: "./tests",
  fullyParallel: true,
  use: {
    ...devices["Desktop Chrome"],
    baseURL: "http://127.0.0.1:4173",
  },
  webServer: {
    command: "npm run build && npm run preview -- --host 127.0.0.1 --port 4173",
    url: "http://127.0.0.1:4173",
    reuseExistingServer: false,
    timeout: 120000,
  },
});

import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";

test("toolchain shell renders the product name", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Footwork" })).toBeVisible();
  await expect(page.getByText("Toolchain shell.")).toBeVisible();
});

test("toolchain shell has no serious accessibility violations", async ({ page }) => {
  await page.goto("/");
  const results = await new AxeBuilder({ page }).analyze();
  const blocking = results.violations.filter(
    (violation) => violation.impact === "serious" || violation.impact === "critical",
  );
  expect(blocking).toEqual([]);
});

